def apply_buyer_fee(apps, schema_editor):
    """
    Off-plan decision 5: the buyer now pays the resale fee on top and the seller gets the full
    price. Open listings move to the new rule; finished ones keep the seller-paid fee they
    were settled with, so the history stays true.
    """
    Listing = apps.get_model("secondary_market", "SecondaryMarketListing")
    pct = Decimal(str(settings.SECONDARY_MARKET_FEE_PERCENT))
    Listing.objects.exclude(status="listed").update(fee_payer="seller")
    for row in Listing.objects.filter(status="listed"):
        row.fee_payer = "buyer"
        row.platform_fee_percent = pct
        row.platform_fee_amount = (row.total_value * pct / Decimal("100")).quantize(
            Decimal("0.01"), ROUND_HALF_UP
        )
        row.net_amount = row.total_value
        row.save(update_fields=[
            "fee_payer", "platform_fee_percent", "platform_fee_amount", "net_amount",
        ])


